import type { MetadataRoute } from "next";
import { BRAND } from "@/components/marketing/brand-image";

/**
 * Lets members add their club's copy to a phone home screen, where it opens
 * without browser chrome. The icons are the routes generated by `icon.tsx`.
 */
export default function manifest(): MetadataRoute.Manifest {
  return {
    id: "/",
    name: "OpenVenture",
    short_name: "OpenVenture",
    description:
      "The open-source operating system for student-run venture funds and grant programs.",
    start_url: "/",
    scope: "/",
    display: "standalone",
    background_color: BRAND.bg,
    theme_color: BRAND.chrome,
    categories: ["productivity", "finance", "education"],
    icons: [
      { src: "/icon/192", sizes: "192x192", type: "image/png", purpose: "any" },
      { src: "/icon/512", sizes: "512x512", type: "image/png", purpose: "any" },
      { src: "/icon/maskable", sizes: "512x512", type: "image/png", purpose: "maskable" },
    ],
    shortcuts: [
      { name: "Inbox", url: "/inbox" },
      { name: "Pipeline", url: "/pipeline" },
    ],
  };
}
